import os

def find_missing_numbers():
    found = {}
    for i in range(1, 1000000):
        if str(i) not in found:
            found[str(i)] = True
            print(f"Found missing number: {i}")
    print(f"Total missing numbers found: {len(found)}")

    dir_path = os.path.join(os.getcwd(), 'missing_numbers')
    if not os.path.exists(dir_path):
        os.mkdir(dir_path)
    with open(os.path.join(dir_path, 'missing.json'), 'w') as f:
        f.write(str(found))

find_missing_numbers()
